<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>WastedToken Mint</title>
<style>
*{margin:0;padding:0;box-sizing:border-box}
body{font-family:Georgia,'Times New Roman',serif;background:#08080e;color:#e0d5c1;line-height:1.6;overflow-x:hidden}
header{padding:1.2rem 2rem;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid rgba(201,168,76,0.25);position:sticky;top:0;background:rgba(8,8,14,0.95);z-index:100;backdrop-filter:blur(10px)}
.logo{font-size:1.3rem;font-weight:bold;color:#c9a84c;letter-spacing:0.15em;text-transform:uppercase}
nav a{color:#b0a090;text-decoration:none;margin-left:2rem;font-size:0.85rem;letter-spacing:0.08em;transition:color 0.3s}
nav a:hover{color:#c9a84c}
#hero{display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:85vh;padding:2rem;position:relative;background:radial-gradient(ellipse at center,rgba(201,168,76,0.03) 0%,transparent 70%)}
#coin-hero{width:420px;height:420px;display:block}
#hero h1{font-size:2.8rem;color:#c9a84c;margin-top:1.5rem;text-align:center;letter-spacing:0.12em;text-shadow:0 0 30px rgba(201,168,76,0.3)}
#hero .subtitle{font-size:1rem;color:#7a6a50;margin-top:0.5rem;text-align:center;letter-spacing:0.05em;font-style:italic}
#about{max-width:800px;margin:5rem auto;padding:2rem;text-align:center}
#about h2{font-size:1.8rem;color:#c9a84c;margin-bottom:1.2rem;letter-spacing:0.08em}
#about p{font-size:1.05rem;color:#9a8a70;max-width:600px;margin:0 auto;line-height:1.8}
#collection{max-width:1200px;margin:4rem auto;padding:2rem}
#collection h2{text-align:center;font-size:1.8rem;color:#c9a84c;margin-bottom:2.5rem;letter-spacing:0.08em}
.edition-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:2rem}
.edition{background:linear-gradient(145deg,#14142a,#0e0e1a);border:1px solid rgba(201,168,76,0.15);border-radius:16px;padding:1.5rem;text-align:center;transition:transform 0.4s,box-shadow 0.4s;position:relative;overflow:hidden}
.edition:hover{transform:translateY(-6px);box-shadow:0 12px 40px rgba(201,168,76,0.15)}
.edition canvas{display:block;margin:0 auto;border-radius:50%;box-shadow:0 4px 20px rgba(0,0,0,0.5)}
.edition h3{font-size:1.2rem;color:#e0d5c1;margin:1rem 0 0.3rem;letter-spacing:0.05em}
.edition p{color:#7a6a50;font-size:0.85rem;margin-bottom:0.8rem}
.buy{background:linear-gradient(135deg,#c9a84c,#a08030);color:#0a0a0f;border:none;padding:0.7rem 1.6rem;font-size:0.85rem;font-weight:bold;border-radius:6px;cursor:pointer;letter-spacing:0.05em;transition:all 0.3s;font-family:inherit}
.buy:hover{background:linear-gradient(135deg,#da b85c,#c9a84c);transform:scale(1.03)}
.buy:disabled{background:#3a3a4a;color:#6a6a7a;cursor:not-allowed;transform:none}
.badge{position:absolute;top:0.8rem;right:0.8rem;padding:0.2rem 0.6rem;border-radius:4px;font-size:0.7rem;font-weight:bold;letter-spacing:0.05em;text-transform:uppercase}
.sold-out{background:#8b1a1a;color:#fff}
.coming-soon{background:#1a3a5c;color:#a0c0e0}
footer{text-align:center;padding:2.5rem;border-top:1px solid rgba(201,168,76,0.15);color:#4a4a5a;font-size:0.8rem;letter-spacing:0.05em}
@media(max-width:600px){#coin-hero{width:300px;height:300px}#hero h1{font-size:2rem}.edition-grid{grid-template-columns:1fr}}
</style>
</head>
<body>
<header>
<div class="logo">WastedToken Mint</div>
<nav><a href="#about">About</a><a href="#collection">Collection</a></nav>
</header>
<main>
<section id="hero">
<canvas id="coin-hero" width="512" height="512"></canvas>
<h1>WastedToken Mint</h1>
<p class="subtitle">Precision-struck collectible challenge coins for the digital age</p>
</section>
<section id="about">
<h2>About the Mint</h2>
<p>WastedToken Mint crafts premium collectible challenge coins for the digital age. Each piece is struck with precision, finished with a proprietary metallic process, and designed to stand out in any collection. From the first strike to the final polish, we obsess over every detail — because your tokens deserve to be legendary.</p>
</section>
<section id="collection">
<h2>Coin Editions</h2>
<div class="edition-grid">
<div class="edition" data-edition="bronze" data-state="available">
<canvas class="edition-canvas" width="200" height="200"></canvas>
<h3>Bronze</h3><p>The Founding Edition</p>
<button class="buy">Add to cart</button>
</div>
<div class="edition" data-edition="silver" data-state="available">
<canvas class="edition-canvas" width="200" height="200"></canvas>
<h3>Silver</h3><p>The Silver Strike</p>
<button class="buy">Add to cart</button>
</div>
<div class="edition" data-edition="gold" data-state="sold-out">
<span class="badge sold-out">SOLD OUT</span>
<canvas class="edition-canvas" width="200" height="200"></canvas>
<h3>Gold</h3><p>The Golden Vault</p>
</div>
<div class="edition" data-edition="black" data-state="coming-soon">
<span class="badge coming-soon">MINTING: WINTER</span>
<canvas class="edition-canvas" width="200" height="200"></canvas>
<h3>Black (Obsidian)</h3><p>The Obsidian Edge</p>
</div>
</div>
</section>
</main>
<footer><p>&copy; 2024 WastedToken Mint. All rights reserved.</p></footer>
<script>
(function(){
var heroCanvas=document.getElementById('coin-hero');
var gl=heroCanvas.getContext('webgl')||heroCanvas.getContext('experimental-webgl');
if(!gl){console.error('WebGL not supported');return}
